public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers.");
    }
    long year = Y;
    int count = 0;
    while (true) {
        if (isLeapYear(year)) {
            count++;
            if (count == N) {
                if (year > Integer.MAX_VALUE) {
                    throw new ArithmeticException("Result exceeds integer range.");
                }
                return (int) year;
            }
        }
        year++;
        if (year > Integer.MAX_VALUE) {
            throw new ArithmeticException("Exceeded integer range while searching for leap year.");
        }
    }
}

private static boolean isLeapYear(long year) {
    if (year % 4 != 0) {
        return false;
    }
